mapper.select:
select fc.company_id,fc.company_code,fc.company_full_name,fc.enabled_flag,nvl(fca.authority_rule_flag,'N') as authorityRuleFlag
from fnd_company fc
left join fnd_company_attribute fca
on fc.company_id = fca.company_id

        fc.ENABLED_FLAG = 'Y'

        and fc.company_id = #{companyId}


        and fc.company_code like concat(concat('%',#{companyCode} ),'%')


        and fc.company_full_name= #{companyFullName}


        and fc.enabled_flag= #{enabledFlag}


order by fc.company_id
